-- i18n: en/es translations of the Atualidades content
-- (7 dossiers and 35 dossier questions x 2 locales =
-- 14 + 70 rows). Only writes dossier_translations and
-- dossier_question_translations; dossiers and dossier_questions (the pt-BR
-- original, including correct_index) are never touched.
--
-- Question options keep exactly the original order: correct_index is
-- positional and is always read from the original row. The join refuses any
-- row whose option count differs from the original.
--
-- Keyed by the real ids read from the live database. Idempotent
-- (on conflict do update). Check afterwards with i18n_atualidades_checkup.sql.

insert into dossier_translations (dossier_id, locale, title, summary, context, what_happened, why_it_happened, who_is_involved, consequences, key_takeaways)
select v.id::uuid, v.locale, v.title, v.summary, v.context, v.what_happened, v.why_it_happened, v.who_is_involved, v.consequences, v.key_takeaways
from (values
  ('7b57c8fd-f92b-4f8b-8d25-d1041db590db', 'en',
   '2026 elections: the race for the presidency officially begins',
   'In August 2026, the candidates for President of the Republic officially launched their election campaigns, marking the start of one of the most decisive periods on Brazil''s political calendar.',
   '2026 is a general election year in Brazil, when the President of the Republic, state governors, senators, and federal and state deputies are elected. The first round of the presidential election is due to take place in October, following the electoral calendar set by the Constitution.',
   'On August 16, 2026, President Luiz Inácio Lula da Silva held his first major campaign event at a stadium in São Bernardo do Campo (SP), seeking re-election. On the same day, Senator Flávio Bolsonaro launched his presidential pre-candidacy at an event in Rio de Janeiro. Street and online election advertising was also allowed from that date on, under the rules of the Superior Electoral Court (TSE).',
   'Brazil''s electoral calendar sets specific dates for campaigns to begin, usually from August of the election year, after candidacies are confirmed at the party conventions.',
   'Luiz Inácio Lula da Silva (seeking re-election), Flávio Bolsonaro (opposition pre-candidate), the TSE (responsible for overseeing the electoral process) and the country''s main political parties.',
   'The result of the 2026 presidential election should set the course of Brazil''s economic, social and foreign policy for the coming years, as well as influence the makeup of the National Congress elected in the same vote.',
   '• 2026 is a general election year in Brazil (president, governors, senators and deputies).
• Campaigns were officially allowed from August 16, 2026.
• The TSE oversees the use of technology and disinformation in campaigns.
• The first round of the presidential election is due to take place in October 2026.'),
  ('2daac094-0b84-45ef-b14f-04ae2da5afa2', 'en',
   'Artificial intelligence in 2026: from novelty to maturity',
   'In 2026, artificial intelligence stops being just a technological novelty and takes on a more pragmatic role, focused on measurable results for companies and governments.',
   'After years of rapid evolution in generative AI models, 2026 is seen as a year of maturity for the sector, with a focus on practical applications rather than just demonstrations of capability.',
   'Among the main trends of 2026 are the evolution of digital assistants into "autonomous agents", able to carry out complete tasks with less human intervention, and the advance of multimodal models, which combine text, images, audio and structured data. The global artificial intelligence sector is expected to exceed US$900 billion in value in 2026, while Brazil plans R$23 billion in AI investment by 2028, through the Brazilian Artificial Intelligence Plan.',
   'This maturity reflects both the technical progress of the models and pressure from companies and governments for concrete financial returns on the large investments made in AI in recent years.',
   'Big tech companies, national governments (including Brazil''s, through its AI plan) and the World Economic Forum, which monitors the technology''s impact on the job market.',
   'According to the World Economic Forum, more than 40% of the skills in demand on the job market are expected to change by the end of the decade, with new roles emerging around the integration, governance and strategic use of artificial intelligence.',
   '• 2026 marks AI''s transition from "novelty" to a phase of maturity and practical results.
• Autonomous agents and multimodal models are the year''s main technology trends.
• The global AI sector is expected to exceed US$900 billion in 2026.
• Brazil plans R$23 billion in AI investment by 2028.'),
  ('c8df7e24-53fe-4843-a1bd-cc2c5f5b7c4f', 'en',
   'Selic falls to 14% as inflation expectations drop',
   'In August 2026, the Monetary Policy Committee (Copom) cut Brazil''s benchmark interest rate, the Selic, to 14% a year, while the financial market revised its inflation projections for the year downward.',
   'The Selic is the Central Bank''s main tool for controlling inflation: when it rises, credit becomes more expensive and consumption tends to slow, easing the pressure on prices; when it falls, the effect is the opposite.',
   'At the meeting that ended on August 5, 2026, Copom cut the Selic by 0.25 percentage point, from 14.25% to 14% a year. According to the Focus Bulletin, published weekly by the Central Bank with the median of the financial market''s projections, expected inflation (measured by the IPCA) for the end of 2026 fell to 5.02%, and the GDP growth projection for the year stood at around 1.98%.',
   'The Selic is cut when the Central Bank judges that inflation is on a downward path and that the economy can handle slightly lower interest rates without reigniting price increases.',
   'The Central Bank of Brazil (responsible for the decision), Copom (the committee that sets the rate) and the financial market (which produces the Focus Bulletin projections).',
   'Lower interest rates tend to stimulate credit, consumption and investment, but the Central Bank remains cautious, since projected inflation (5.02%) is still above the center of the country''s official target.',
   '• The Selic was cut to 14% a year at the Copom meeting of August 5, 2026.
• Projected inflation (IPCA) for 2026 is 5.02%, according to the Focus Bulletin.
• The GDP growth projection for 2026 is around 1.98%.
• Interest rates and inflation are central, recurring topics in current affairs and economics exams.'),
  ('b93abc5d-de4a-4a5d-9d68-2d67ec4ab406', 'en',
   'After COP30, the world prepares for COP31 in Turkey',
   'With COP30 over, the international climate agenda turns its attention to COP31, scheduled for November 2026 in Antalya, Turkey.',
   'The COP (Conference of the Parties) is the UN''s main annual meeting on climate change, bringing together practically every country in the world to negotiate targets and commitments to cut greenhouse gas emissions.',
   'COP31 will be held in Antalya, Turkey, from November 9 to 20, 2026, in an unprecedented shared-presidency format: Turkey as host country and Australia leading the negotiations. World Environment Day 2026, celebrated on June 5, had climate change as its theme, with the "Act Now for the Climate" campaign promoted by UNEP (the United Nations Environment Programme).',
   'The last eleven years have been the hottest ever recorded globally, and the world is on track to temporarily exceed the 1.5°C warming limit set by the Paris Agreement, which keeps up international pressure for new targets and more effective action.',
   'The UN (through the UNFCCC, the framework convention on climate change), national governments, UNEP, civil society organizations and the private sector.',
   'COP31 is expected to discuss progress on commitments made at previous conferences, climate finance for developing countries and strategies to adapt to extreme weather events, which are increasingly frequent.',
   '• COP31 takes place in Antalya, Turkey, from November 9 to 20, 2026.
• For the first time, the conference will have a presidency shared by two countries (Turkey and Australia).
• The last eleven years have been the hottest ever recorded on the planet.
• The world is close to temporarily exceeding the Paris Agreement''s 1.5°C limit.'),
  ('19e3cd41-3d6f-4f4e-b153-62f91f28fd1b', 'en',
   'The world''s main armed conflicts in 2026',
   '2026 began with the world dealing with multiple simultaneous armed conflicts, from protracted wars to tensions at risk of escalation.',
   'International analysts describe 2026 as a year of high geopolitical instability, with conflicts ranging from Eastern Europe to the Middle East, as well as Africa and Asia.',
   'Among the main conflicts monitored in 2026 are the war in Ukraine (which has settled into a war of attrition, with massive use of drones and attacks on infrastructure), the conflict between Israel and Palestinian groups in the Gaza Strip, the civil war in Sudan (intensified in regions such as Darfur), the crisis in the Democratic Republic of the Congo, the internal conflict in Myanmar and the war in Yemen. Tension between China and Taiwan also remains one of the points most closely watched by the international community.',
   'Each conflict has its own specific causes (territorial disputes, ethnic, religious or political tensions, and disputes over resources), but they all share the backdrop of an increasingly fragmented international order, with less capacity for mediation by multilateral bodies such as the UN.',
   'National governments, rebel forces and militias, international organizations (such as the UN and NATO) and regional and global powers that support different sides, directly or indirectly.',
   'These conflicts cause humanitarian crises, population displacement and global economic impacts (on trade routes and commodity prices), and they often appear as a topic in current affairs questions in university entrance and civil service exams.',
   '• The main armed conflicts of 2026 include Ukraine, Gaza, Sudan, the DRC, Myanmar and Yemen.
• Tension between China and Taiwan is one of the most closely watched points worldwide.
• Regional conflicts have specific causes but reflect a more fragmented international order.
• The topic recurs in current affairs questions in university entrance and civil service exams.'),
  ('1db31507-71eb-490b-969a-f02ad25c6671', 'en',
   'Brazil monitors an Ebola outbreak in Africa and moves ahead with a health emergency center',
   'In 2026, Brazilian health authorities are closely following an Ebola outbreak identified in the Democratic Republic of the Congo, while the country moves ahead with creating a national structure for health emergencies.',
   'After the COVID-19 pandemic, countries around the world began investing in permanent structures for public health surveillance and emergency response, to avoid repeating the coordination failures seen between 2020 and 2022.',
   'An Ebola outbreak was identified in May 2026 in Ituri province, in the Democratic Republic of the Congo. In Brazil, two suspected cases were reported by health authorities, although the risk of the disease being introduced and spreading in the country is considered low. At the same time, Brazil is working to create, by the end of 2026, the Brazilian Center for Public Health Emergencies (Cbesp), a national structure for responding to epidemics, outbreaks and other emergencies, including climate events with a direct impact on the population''s health.',
   'Cbesp is meant precisely to keep the country from repeating the coordination failures seen during the COVID-19 pandemic, centralizing the response to different types of health emergency in a single structure.',
   'The Ministry of Health, the SUS (Brazil''s Unified Health System), international health organizations (which monitor the outbreak in Africa) and the health authorities of the Democratic Republic of the Congo.',
   'Although the immediate risk to Brazil is considered low, the episode reinforces the importance of epidemiological surveillance systems ready to quickly identify and contain potential threats, and speeds up discussions on creating the new emergency center.',
   '• An Ebola outbreak was identified in May 2026 in the Democratic Republic of the Congo.
• Brazil reported suspected cases, but the risk of spread in the country is considered low.
• Brazil plans to create Cbesp (the Brazilian Center for Public Health Emergencies) by the end of 2026.
• The initiative seeks to avoid coordination failures like those seen during the COVID-19 pandemic.'),
  ('6035c5f5-af34-4b9a-9a85-56d6edcb090a', 'en',
   'Political education becomes part of the curriculum in Brazilian schools',
   'In 2026, teaching political education and citizenship rights became mandatory in Brazilian basic education, following changes to education law.',
   'The Law of Guidelines and Bases of National Education (LDB) defines the mandatory content taught in the country''s schools. Historically, topics such as how the State works and democratic participation were covered only occasionally, with no formal, unified requirement.',
   'According to a report by Agência Brasil, a change to the LDB made it mandatory for schools to cover political education and citizenship rights, integrating this content into the subjects that deal with the country''s social and political reality. The stated goal is to ensure that students have access to practical teaching on how the State is organized, the channels for democratic participation and how society works in general.',
   'The measure is presented as a response to the need to strengthen students'' civic education, in a context of low political participation among young people and concern about fighting disinformation.',
   'The National Congress (responsible for approving the change in the law), the Ministry of Education and the public and private school systems, which need to adapt their curricula.',
   'The measure is expected to help produce students who are better prepared to take part in public debate and the electoral process, although its effectiveness will depend on how it is implemented in the classroom.',
   '• Political education and citizenship rights became mandatory content in basic education.
• The change was incorporated into the LDB (Law of Guidelines and Bases of National Education).
• The goal is to strengthen students'' civic education and democratic participation.
• The topic joins other mandatory subjects in the curriculum, such as Afro-Brazilian and Indigenous history and culture.'),
  ('7b57c8fd-f92b-4f8b-8d25-d1041db590db', 'es',
   'Elecciones 2026: la carrera por la Presidencia comienza oficialmente',
   'En agosto de 2026, los candidatos a la Presidencia de la República dieron inicio oficialmente a las campañas electorales, marcando el comienzo de uno de los períodos más decisivos del calendario político brasileño.',
   '2026 es año de elecciones generales en Brasil, en las que se eligen el presidente de la República, los gobernadores, los senadores y los diputados federales y estatales. La primera vuelta de la elección presidencial debe celebrarse en octubre, según el calendario electoral fijado por la Constitución.',
   'El 16 de agosto de 2026, el presidente Luiz Inácio Lula da Silva realizó su primer gran acto de campaña en un estadio de São Bernardo do Campo (SP), en busca de la reelección. Ese mismo día, el senador Flávio Bolsonaro lanzó su precandidatura a la Presidencia en un evento en Río de Janeiro. La propaganda electoral en las calles y en internet también quedó autorizada a partir de esa fecha, según las normas del Tribunal Superior Electoral (TSE).',
   'El calendario electoral brasileño establece fechas específicas para el inicio de las campañas, generalmente a partir de agosto del año electoral, después de la definición de las candidaturas en las convenciones partidarias.',
   'Luiz Inácio Lula da Silva (en busca de la reelección), Flávio Bolsonaro (precandidato de la oposición), el TSE (responsable de fiscalizar el proceso electoral) y los principales partidos políticos del país.',
   'El resultado de la elección presidencial de 2026 debe definir el rumbo de la política económica, social y exterior de Brasil en los próximos años, además de influir en la composición del Congreso Nacional elegido en los mismos comicios.',
   '• 2026 es año de elecciones generales en Brasil (presidente, gobernadores, senadores y diputados).
• Las campañas quedaron oficialmente autorizadas el 16 de agosto de 2026.
• El TSE fiscaliza el uso de la tecnología y la desinformación en las campañas.
• La primera vuelta de la elección presidencial debe celebrarse en octubre de 2026.'),
  ('2daac094-0b84-45ef-b14f-04ae2da5afa2', 'es',
   'Inteligencia artificial en 2026: de la novedad a la madurez',
   'En 2026, la inteligencia artificial deja de ser solo una novedad tecnológica para asumir un papel más pragmático, centrado en resultados medibles para empresas y gobiernos.',
   'Tras años de rápida evolución de los modelos de IA generativa, 2026 se señala como un año de maduración del sector, centrado en aplicaciones prácticas en lugar de meras demostraciones de capacidad.',
   'Entre las principales tendencias de 2026 están la evolución de los asistentes digitales hacia "agentes autónomos", capaces de ejecutar tareas completas con menor intervención humana, y el avance de los modelos multimodales, que combinan texto, imagen, audio y datos estructurados. Se espera que el sector global de la inteligencia artificial supere los US$ 900 mil millones en valor en 2026, mientras que Brasil prevé R$ 23 mil millones en inversiones en IA hasta 2028, por medio del Plan Brasileño de Inteligencia Artificial.',
   'La maduración refleja tanto el avance técnico de los modelos como la presión de empresas y gobiernos por un retorno financiero concreto de las grandes inversiones realizadas en IA en los últimos años.',
   'Grandes empresas tecnológicas, gobiernos nacionales (incluido el gobierno brasileño, por medio de su plan de IA) y el Foro Económico Mundial, que monitorea los impactos de la tecnología en el mercado laboral.',
   'Según el Foro Económico Mundial, más del 40% de las habilidades demandadas en el mercado laboral deben cambiar antes del fin de la década, con el surgimiento de nuevas funciones vinculadas a la integración, la gobernanza y el uso estratégico de la inteligencia artificial.',
   '• 2026 marca la transición de la IA de "novedad" a una fase de madurez y resultados prácticos.
• Los agentes autónomos y los modelos multimodales son las principales tendencias tecnológicas del año.
• Se espera que el sector global de IA supere los US$ 900 mil millones en 2026.
• Brasil prevé R$ 23 mil millones en inversiones en IA hasta 2028.'),
  ('c8df7e24-53fe-4843-a1bd-cc2c5f5b7c4f', 'es',
   'La Selic baja al 14% en medio de la caída de la expectativa de inflación',
   'En agosto de 2026, el Comité de Política Monetaria (Copom) redujo la tasa básica de interés, la Selic, al 14% anual, mientras el mercado financiero revisaba a la baja sus proyecciones de inflación para el año.',
   'La Selic es el principal instrumento del Banco Central para controlar la inflación: cuando sube, el crédito se encarece y el consumo tiende a desacelerarse, lo que reduce la presión sobre los precios; cuando baja, el efecto es el opuesto.',
   'En la reunión concluida el 5 de agosto de 2026, el Copom redujo la Selic en 0,25 punto porcentual, del 14,25% al 14% anual. Según el Boletín Focus, publicado semanalmente por el Banco Central con la mediana de las proyecciones del mercado financiero, la expectativa de inflación (medida por el IPCA) para el cierre de 2026 bajó al 5,02%, y la proyección de crecimiento del PIB para el año quedó en torno al 1,98%.',
   'La reducción de la Selic se produce cuando el Banco Central evalúa que la inflación sigue una trayectoria descendente y que la economía puede soportar tasas de interés un poco más bajas sin reavivar el alza de precios.',
   'El Banco Central de Brasil (responsable de la decisión), el Copom (comité que define la tasa) y el mercado financiero (que elabora las proyecciones del Boletín Focus).',
   'Las tasas de interés más bajas tienden a estimular el crédito, el consumo y las inversiones, pero el Banco Central sigue siendo cauteloso, ya que la inflación proyectada (5,02%) todavía está por encima del centro de la meta oficial que persigue el país.',
   '• La Selic se redujo al 14% anual en la reunión del Copom del 5 de agosto de 2026.
• La inflación proyectada (IPCA) para 2026 es del 5,02%, según el Boletín Focus.
• La proyección de crecimiento del PIB para 2026 ronda el 1,98%.
• Las tasas de interés y la inflación son temas centrales y recurrentes en los exámenes de actualidad y economía.'),
  ('b93abc5d-de4a-4a5d-9d68-2d67ec4ab406', 'es',
   'Después de la COP30, el mundo se prepara para la COP31 en Turquía',
   'Con la COP30 ya concluida, la atención de la agenda climática internacional se dirige a la COP31, prevista para noviembre de 2026 en Antalya, Turquía.',
   'La COP (Conferencia de las Partes) es el principal encuentro anual de la ONU sobre el cambio climático y reúne a prácticamente todos los países del mundo para negociar metas y compromisos de reducción de emisiones de gases de efecto invernadero.',
   'La COP31 se celebrará en Antalya, Turquía, del 9 al 20 de noviembre de 2026, en un formato inédito de presidencia compartida: Turquía como país anfitrión y Australia al frente de las negociaciones. El Día Mundial del Medio Ambiente de 2026, celebrado el 5 de junio, tuvo como tema el cambio climático, con la campaña "Ahora por el Clima" promovida por el PNUMA (Programa de las Naciones Unidas para el Medio Ambiente).',
   'Los últimos once años han sido los más cálidos jamás registrados a nivel global, y el mundo se encamina a superar temporalmente el límite de 1,5 °C de calentamiento establecido por el Acuerdo de París, lo que mantiene la presión internacional por nuevas metas y acciones más eficaces.',
   'La ONU (por medio de la CMNUCC, la convención marco sobre el cambio climático), los gobiernos nacionales, el PNUMA, organizaciones de la sociedad civil y el sector privado.',
   'La COP31 debe discutir el avance de los compromisos asumidos en conferencias anteriores, la financiación climática para los países en desarrollo y las estrategias de adaptación a eventos climáticos extremos, cada vez más frecuentes.',
   '• La COP31 se celebra en Antalya, Turquía, del 9 al 20 de noviembre de 2026.
• Por primera vez, la conferencia tendrá una presidencia compartida entre dos países (Turquía y Australia).
• Los últimos once años han sido los más cálidos jamás registrados en el planeta.
• El mundo está cerca de superar temporalmente el límite de 1,5 °C del Acuerdo de París.'),
  ('19e3cd41-3d6f-4f4e-b153-62f91f28fd1b', 'es',
   'Los principales conflictos armados del mundo en 2026',
   'El año 2026 llegó con el mundo lidiando con múltiples conflictos armados simultáneos, desde guerras prolongadas hasta tensiones con riesgo de escalada.',
   'Los analistas internacionales señalan 2026 como un año de elevada inestabilidad geopolítica, con conflictos que van de Europa del Este a Oriente Medio, pasando por África y Asia.',
   'Entre los principales conflictos monitoreados en 2026 están la guerra en Ucrania (que se consolidó como un conflicto de desgaste, con uso masivo de drones y ataques a la infraestructura), el conflicto entre Israel y grupos palestinos en la Franja de Gaza, la guerra civil en Sudán (intensificada en regiones como Darfur), la crisis en la República Democrática del Congo, el conflicto interno en Myanmar y la guerra en Yemen. La tensión entre China y Taiwán también sigue siendo uno de los puntos más observados por la comunidad internacional.',
   'Cada conflicto tiene causas propias y específicas (disputas territoriales, tensiones étnicas, religiosas o políticas y disputas por recursos), pero todos comparten el telón de fondo de un orden internacional cada vez más fragmentado, con menor capacidad de mediación de organismos multilaterales como la ONU.',
   'Gobiernos nacionales, fuerzas rebeldes y milicias, organizaciones internacionales (como la ONU y la OTAN) y potencias regionales y globales que apoyan a distintos bandos, directa o indirectamente.',
   'Estos conflictos generan crisis humanitarias, desplazamiento de poblaciones e impactos económicos globales (en rutas comerciales y precios de las materias primas), y aparecen con frecuencia como tema en las preguntas de actualidad de los exámenes de ingreso a la universidad y de oposiciones.',
   '• Los principales conflictos armados de 2026 incluyen Ucrania, Gaza, Sudán, la RDC, Myanmar y Yemen.
• La tensión entre China y Taiwán es uno de los puntos más observados a nivel mundial.
• Los conflictos regionales tienen causas específicas, pero reflejan un orden internacional más fragmentado.
• El tema es recurrente en las preguntas de actualidad de los exámenes de ingreso a la universidad y de oposiciones.'),
  ('1db31507-71eb-490b-969a-f02ad25c6671', 'es',
   'Brasil monitorea un brote de ébola en África y avanza en la creación de un centro de emergencias sanitarias',
   'En 2026, las autoridades sanitarias brasileñas siguen de cerca un brote de ébola identificado en la República Democrática del Congo, mientras el país avanza en la creación de una estructura nacional para emergencias sanitarias.',
   'Después de la pandemia de COVID-19, países de todo el mundo pasaron a invertir en estructuras permanentes de vigilancia y respuesta a emergencias de salud pública, para evitar repetir los fallos de coordinación observados entre 2020 y 2022.',
   'En mayo de 2026 se identificó un brote de ébola en la provincia de Ituri, en la República Democrática del Congo. En Brasil, las autoridades sanitarias notificaron dos casos sospechosos, aunque el riesgo de introducción y propagación de la enfermedad en el país se considera bajo. Paralelamente, Brasil trabaja para crear, antes del fin de 2026, el Centro Brasileño de Emergencias en Salud Pública (Cbesp), una estructura nacional dedicada a enfrentar epidemias, brotes y otras emergencias, incluidos los eventos climáticos con impacto directo en la salud de la población.',
   'La creación del Cbesp busca precisamente evitar que el país repita los fallos de coordinación observados durante la pandemia de COVID-19, centralizando la respuesta a distintos tipos de emergencia sanitaria en una única estructura.',
   'El Ministerio de Salud, el SUS (Sistema Único de Salud de Brasil), organizaciones internacionales de salud (que monitorean el brote en África) y las autoridades sanitarias de la República Democrática del Congo.',
   'Aunque el riesgo inmediato para Brasil se considera bajo, el episodio refuerza la importancia de contar con sistemas de vigilancia epidemiológica preparados para identificar y contener rápidamente posibles amenazas, y acelera las discusiones sobre la creación del nuevo centro de emergencias.',
   '• En mayo de 2026 se identificó un brote de ébola en la República Democrática del Congo.
• Brasil notificó casos sospechosos, pero el riesgo de propagación en el país se considera bajo.
• Brasil planea crear el Cbesp (Centro Brasileño de Emergencias en Salud Pública) antes del fin de 2026.
• La iniciativa busca evitar fallos de coordinación como los vistos durante la pandemia de COVID-19.'),
  ('6035c5f5-af34-4b9a-9a85-56d6edcb090a', 'es',
   'La educación política pasa a formar parte del currículo de las escuelas brasileñas',
   'En 2026, la enseñanza de educación política y derechos de ciudadanía pasó a ser obligatoria en la educación básica brasileña, según cambios en la legislación educativa.',
   'La Ley de Directrices y Bases de la Educación Nacional (LDB) define los contenidos obligatorios que se enseñan en las escuelas del país. Históricamente, temas como el funcionamiento del Estado y la participación democrática se abordaban de forma puntual, sin una obligatoriedad formal y unificada.',
   'Según un reportaje de la Agência Brasil, un cambio en la LDB hizo obligatorio abordar la educación política y los derechos de ciudadanía en las escuelas, integrando estos contenidos en las asignaturas que tratan la realidad social y política del país. El objetivo declarado es garantizar que los estudiantes tengan acceso a enseñanzas prácticas sobre la organización del Estado, los canales de participación democrática y el funcionamiento general de la sociedad.',
   'La medida se presenta como respuesta a la necesidad de fortalecer la formación ciudadana de los estudiantes, en un contexto de baja participación política de los jóvenes y de preocupación por combatir la desinformación.',
   'El Congreso Nacional (responsable de aprobar el cambio en la legislación), el Ministerio de Educación y las redes de enseñanza públicas y privadas, que deben adaptar sus currículos.',
   'Se espera que la medida contribuya a formar estudiantes mejor preparados para participar en el debate público y en el proceso electoral, aunque su eficacia dependerá de cómo se implemente en el aula.',
   '• La educación política y los derechos de ciudadanía pasaron a ser contenidos obligatorios en la educación básica.
• El cambio se incorporó a la LDB (Ley de Directrices y Bases de la Educación Nacional).
• El objetivo es fortalecer la formación ciudadana y la participación democrática de los estudiantes.
• El tema se suma a otros contenidos obligatorios del currículo, como la historia y la cultura afrobrasileña e indígena.')
) as v(id, locale, title, summary, context, what_happened, why_it_happened, who_is_involved, consequences, key_takeaways)
join dossiers d on d.id = v.id::uuid
on conflict (dossier_id, locale) do update
  set title = excluded.title,
      summary = excluded.summary,
      context = excluded.context,
      what_happened = excluded.what_happened,
      why_it_happened = excluded.why_it_happened,
      who_is_involved = excluded.who_is_involved,
      consequences = excluded.consequences,
      key_takeaways = excluded.key_takeaways;

